changeSet.sql:
CREATE TABLE deployment_plans ( id UUID PRIMARY KEY, environment VARCHAR(40) NOT NULL, tag VARCHAR(128) NOT NULL, status VARCHAR(16) NOT NULL CHECK (status IN ('running', 'succeeded', 'failed', 'rolled_back')), origin VARCHAR(16) NOT NULL CHECK (origin IN ('local', 'observed')), initiator VARCHAR(200) NOT NULL, initiator_user_id INTEGER NULL REFERENCES users(id) ON DELETE SET NULL, reason TEXT NULL, abandoned_by VARCHAR(200) NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), finished_at TIMESTAMPTZ NULL, last_activity_at TIMESTAMPTZ NOT NULL DEFAULT now() );
-- The history lists newest first. CREATE INDEX idx_deployment_plans_created ON deployment_plans (created_at DESC);
-- At most one running plan that this Logos started, per environment. CREATE UNIQUE INDEX uq_deployment_plans_one_running ON deployment_plans (environment) WHERE status = 'running' AND origin = 'local';

CREATE TABLE deployment_steps ( id UUID PRIMARY KEY, plan_id UUID NOT NULL REFERENCES deployment_plans(id) ON DELETE CASCADE, position INTEGER NOT NULL, kind VARCHAR(16) NOT NULL CHECK (kind IN ('core', 'worker')), deployer_id UUID NULL REFERENCES deployers(id) ON DELETE SET NULL, deployer_name VARCHAR(100) NOT NULL, status VARCHAR(16) NOT NULL CHECK (status IN ('waiting', 'ordered', 'running', 'succeeded', 'unchanged', 'rolled_back', 'failed', 'cancelled')), phase VARCHAR(16) NULL, failure VARCHAR(40) NULL, message TEXT NULL, requested_by VARCHAR(300) NULL, started_at TIMESTAMPTZ NULL, finished_at TIMESTAMPTZ NULL, last_activity_at TIMESTAMPTZ NOT NULL DEFAULT now(), events JSONB NOT NULL DEFAULT '[]'::jsonb, failure_logs TEXT NULL, details JSONB NULL );
CREATE INDEX idx_deployment_steps_plan ON deployment_steps (plan_id, position);
-- A deployer asks for the steps that are ordered and not yet taken. CREATE INDEX idx_deployment_steps_open_orders ON deployment_steps (deployer_id) WHERE status = 'ordered';
-- The sweep for silent deployers looks at the steps that have not ended. CREATE INDEX idx_deployment_steps_active ON deployment_steps (last_activity_at) WHERE status IN ('ordered', 'running');
